/**
 * Environment contract of workspace-service.
 *
 * Binding types are generated by `wrangler types` into `worker-configuration.d.ts`.
 * The service owns its database and is not exposed outward: only the gateway is
 * public, inside there is only its Service Binding.
 */
export interface Bindings {
  DB: D1Database;
  /** User profiles: email and name come from auth-service. */
  AUTH_SERVICE: Fetcher;
  ENVIRONMENT: string;
  SERVICE_VERSION: string;
  /** Public gateway address: the invitation link is built from it. */
  PUBLIC_GATEWAY_URL: string;
  /** Public frontend address: also part of the invitation link. */
  PUBLIC_APP_URL: string;
  /** Lifetime of an invitation link in days. */
  INVITATION_TTL_DAYS: string;
  /**
   * How long an archived workspace lives before cron deletes it.
   * The archive is temporary: otherwise deleted workspaces would pile up forever.
   */
  ARCHIVE_RETENTION_DAYS: string;
  /** Maximum active invitations per workspace so links cannot flood it. */
  MAX_ACTIVE_INVITATIONS: string;
}

export type AppEnv = {
  Bindings: Bindings;
};
